namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string Category { get; set; } = "";
    public string Description { get; set; } = "";
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public int TotalRatingPoints { get; set; }
    public int RatingCount { get; set; }
    public double AverageRating => RatingCount > 0 ? (double)TotalRatingPoints / RatingCount : 0;
}

public static class RecipeStore
{
    private static int _nextId = 7;

    public static List<Recipe> Recipes { get; } =
    [
        new()
        {
            Id = 1, Title = "Classic Margherita Pizza", Category = "Italian",
            Description = "A simple and delicious pizza with fresh tomatoes, mozzarella, and basil.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps = ["Preheat oven to 475°F.", "Roll out dough on a floured surface.", "Spread crushed tomatoes over the dough.", "Add sliced mozzarella.", "Bake for 10–12 minutes.", "Top with fresh basil and a drizzle of olive oil."],
            TotalRatingPoints = 14, RatingCount = 3
        },
        new()
        {
            Id = 2, Title = "Spaghetti Carbonara", Category = "Italian",
            Description = "Creamy pasta with eggs, cheese, pancetta, and black pepper.",
            Ingredients = ["Spaghetti", "Pancetta", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps = ["Cook spaghetti in salted boiling water.", "Fry pancetta until crispy.", "Whisk eggs with grated Pecorino and pepper.", "Toss hot pasta with pancetta.", "Remove from heat, stir in egg mixture quickly.", "Serve immediately with extra cheese."],
            TotalRatingPoints = 9, RatingCount = 2
        },
        new()
        {
            Id = 3, Title = "Chicken Tikka Masala", Category = "Indian",
            Description = "Tender chicken in a rich, spiced tomato-cream sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Tomato sauce", "Heavy cream", "Onion", "Garlic", "Ginger"],
            Steps = ["Marinate chicken in yogurt and spices for 1 hour.", "Grill or pan-fry chicken until charred.", "Sauté onion, garlic, and ginger.", "Add tomato sauce and simmer.", "Stir in cream and garam masala.", "Add chicken, simmer 10 minutes."],
            TotalRatingPoints = 5, RatingCount = 1
        },
        new()
        {
            Id = 4, Title = "Tacos al Pastor", Category = "Mexican",
            Description = "Marinated pork tacos with pineapple, cilantro, and onion.",
            Ingredients = ["Pork shoulder", "Dried chiles", "Pineapple", "Corn tortillas", "Cilantro", "White onion", "Lime"],
            Steps = ["Blend dried chiles with spices to make marinade.", "Marinate pork for at least 2 hours.", "Grill pork and pineapple slices.", "Dice pork and pineapple.", "Warm tortillas.", "Assemble tacos with pork, pineapple, onion, and cilantro."],
            TotalRatingPoints = 10, RatingCount = 2
        },
        new()
        {
            Id = 5, Title = "Chocolate Lava Cake", Category = "Desserts",
            Description = "Rich chocolate cakes with a molten center.",
            Ingredients = ["Dark chocolate", "Butter", "Eggs", "Sugar", "Flour", "Vanilla extract"],
            Steps = ["Preheat oven to 425°F.", "Melt chocolate and butter together.", "Whisk eggs, sugar, and vanilla.", "Fold in melted chocolate, then flour.", "Pour into greased ramekins.", "Bake 12–14 minutes until edges are set but center jiggles."],
            TotalRatingPoints = 15, RatingCount = 3
        },
        new()
        {
            Id = 6, Title = "Pad Thai", Category = "Asian",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and tamarind sauce.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
            Steps = ["Soak rice noodles in warm water.", "Make sauce: mix tamarind paste, fish sauce, and sugar.", "Stir-fry shrimp, then push aside and scramble eggs.", "Add drained noodles and sauce.", "Toss with bean sprouts.", "Serve with crushed peanuts and lime wedges."],
            TotalRatingPoints = 8, RatingCount = 2
        }
    ];

    public static IEnumerable<string> GetCategories() =>
        Recipes.Select(r => r.Category).Distinct().Order();

    public static IEnumerable<Recipe> GetByCategory(string category) =>
        Recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase));

    public static Recipe? GetById(int id) =>
        Recipes.FirstOrDefault(r => r.Id == id);

    public static void Add(Recipe recipe)
    {
        recipe.Id = Interlocked.Increment(ref _nextId);
        Recipes.Add(recipe);
    }
}

@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes</PageTitle>

<h2>@CategoryName Recipes</h2>
<nav aria-label="breadcrumb">
    <ol class="breadcrumb">
        <li class="breadcrumb-item"><a href="/">Home</a></li>
        <li class="breadcrumb-item active">@CategoryName</li>
    </ol>
</nav>

@if (recipes.Any())
{
    <div class="row row-cols-1 row-cols-md-2 g-4">
        @foreach (var recipe in recipes)
        {
            <div class="col">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        @if (recipe.RatingCount > 0)
                        {
                            <p class="text-warning mb-2">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    @(i <= Math.Round(recipe.AverageRating) ? "★" : "☆")
                                }
                                <span class="text-muted ms-1">(@recipe.RatingCount)</span>
                            </p>
                        }
                        <a href="/recipe/@recipe.Id" class="btn btn-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <div class="alert alert-info">No recipes found in this category.</div>
}

@code {
    [Parameter] public string CategoryName { get; set; } = "";
    private IEnumerable<RecipeCommunity.Models.Recipe> recipes = [];

    protected override void OnParametersSet()
    {
        recipes = RecipeCommunity.Models.RecipeStore.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"

@if (recipe is not null)
{
    <PageTitle>@recipe.Title</PageTitle>

    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item"><a href="/category/@recipe.Category">@recipe.Category</a></li>
            <li class="breadcrumb-item active">@recipe.Title</li>
        </ol>
    </nav>

    <h2>@recipe.Title</h2>
    <p class="lead">@recipe.Description</p>

    <StarRating RecipeId="recipe.Id" @rendermode="InteractiveServer" />

    <div class="row mt-4">
        <div class="col-md-5">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">🧾 Ingredients</h5></div>
                <ul class="list-group list-group-flush">
                    @foreach (var ingredient in recipe.Ingredients)
                    {
                        <li class="list-group-item">@ingredient</li>
                    }
                </ul>
            </div>
        </div>
        <div class="col-md-7">
            <div class="card">
                <div class="card-header"><h5 class="mb-0">👩‍🍳 Steps</h5></div>
                <ol class="list-group list-group-numbered list-group-flush">
                    @foreach (var step in recipe.Steps)
                    {
                        <li class="list-group-item">@step</li>
                    }
                </ol>
            </div>
        </div>
    </div>
}
else
{
    <PageTitle>Recipe Not Found</PageTitle>
    <div class="alert alert-warning">Recipe not found.</div>
    <a href="/" class="btn btn-primary">Back to Home</a>
}

@code {
    [Parameter] public int Id { get; set; }
    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeCommunity.Models.RecipeStore.GetById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<h2>📝 Submit a Recipe</h2>
<p>Share your favorite recipe with the community!</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Recipe submitted!</h4>
        <p>Your recipe "<strong>@model.Title</strong>" has been added.</p>
        <a href="/recipe/@submittedId" class="btn btn-primary me-2">View Recipe</a>
        <button class="btn btn-outline-secondary" @onclick="Reset">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="submitRecipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label class="form-label">Recipe Title</label>
            <InputText @bind-Value="model.Title" class="form-control" placeholder="e.g. Grandma's Apple Pie" />
            <ValidationMessage For="() => model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label class="form-label">Category</label>
            <InputSelect @bind-Value="model.Category" class="form-select">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Mexican">Mexican</option>
                <option value="Asian">Asian</option>
                <option value="Desserts">Desserts</option>
                <option value="Other">Other</option>
            </InputSelect>
            <ValidationMessage For="() => model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label class="form-label">Description</label>
            <InputTextArea @bind-Value="model.Description" class="form-control" rows="2"
                placeholder="A short description of the dish" />
        </div>

        <div class="mb-3">
            <label class="form-label">Ingredients <small class="text-muted">(one per line)</small></label>
            <InputTextArea @bind-Value="ingredientsText" class="form-control" rows="5"
                placeholder="2 cups flour&#10;1 cup sugar&#10;3 eggs" />
        </div>

        <div class="mb-3">
            <label class="form-label">Steps <small class="text-muted">(one per line)</small></label>
            <InputTextArea @bind-Value="stepsText" class="form-control" rows="5"
                placeholder="Preheat oven to 350°F.&#10;Mix dry ingredients.&#10;Bake for 30 minutes." />
        </div>

        <button type="submit" class="btn btn-success btn-lg">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel model = new();
    private string ingredientsText = "";
    private string stepsText = "";
    private bool submitted;
    private int submittedId;

    private void HandleSubmit()
    {
        var recipe = new RecipeCommunity.Models.Recipe
        {
            Title = model.Title,
            Category = model.Category,
            Description = model.Description ?? "",
            Ingredients = ParseLines(ingredientsText),
            Steps = ParseLines(stepsText)
        };

        RecipeCommunity.Models.RecipeStore.Add(recipe);
        submittedId = recipe.Id;
        submitted = true;
    }

    private void Reset()
    {
        model = new();
        ingredientsText = "";
        stepsText = "";
        submitted = false;
    }

    private static List<string> ParseLines(string text) =>
        (text ?? "")
            .Split('\n', StringSplitOptions.RemoveEmptyEntries)
            .Select(l => l.Trim())
            .Where(l => l.Length > 0)
            .ToList();

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string Category { get; set; } = "";

        public string? Description { get; set; }
    }
}

