{"path": "/tmp/sv-2d874738253f44b58971fb896256c6e1/RecipeCommunity/Components/StarRating.razor", "file_text": "
<div class="my-3">
    <span class="me-2"><strong>Rate this recipe:</strong></span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span role="button" style="font-size:1.5rem; cursor:pointer; color:@(star <= (hovered > 0 ? hovered : selected) ? "#ffc107" : "#ccc")"
              @onmouseover="() => hovered = star"
              @onmouseout="() => hovered = 0"
              @onclick="() => SubmitRating(star)">★</span>
    }
    @if (justRated)
    {
        <span class="text-success ms-2">Thanks for rating!</span>
    }
    @if (recipe is not null && recipe.RatingCount > 0)
    {
        <div class="text-muted small mt-1">
            Average: @recipe.AverageRating.ToString("F1") / 5 (@recipe.RatingCount ratings)
        </div>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }

    private int hovered;
    private int selected;
    private bool justRated;
    private RecipeCommunity.Models.Recipe? recipe;

    protected override void OnParametersSet()
    {
        recipe = RecipeCommunity.Models.RecipeStore.GetById(RecipeId);
    }

    private void SubmitRating(int stars)
    {
        if (recipe is null) return;
        selected = stars;
        recipe.TotalRatingPoints += stars;
        recipe.RatingCount++;
        justRated = true;
    }
}
"}

